  'Creator publishing' => 'સર્જક પ્રકાશન',
  'Creator Studio content management uses the same visibility model: public, unlisted, or private. Scheduled videos use requested visibility after release.' => 'નિર્માતા સ્ટુડિયો સામગ્રી સંચાલન સમાન દૃશ્યતા મોડેલનો ઉપયોગ કરે છે: સાર્વજનિક, અસૂચિબદ્ધ અથવા ખાનગી. અનુસૂચિત વિડિઓઝ રિલીઝ પછી વિનંતી કરેલ દૃશ્યતાનો ઉપયોગ કરે છે.',
  'Creator tools' => 'સર્જક સાધનો',
  'Creator uploads' => 'નિર્માતા અપલોડ્સ',
  'Creators can upload videos, manage visibility, add thumbnails and captions, publish scheduled content, review their library, and track content from Creator Studio.' => 'સર્જકો વીડિયો અપલોડ કરી શકે છે, દૃશ્યતાનું સંચાલન કરી શકે છે, થંબનેલ્સ અને કૅપ્શન્સ ઉમેરી શકે છે, શેડ્યૂલ કરેલી સામગ્રી પ્રકાશિત કરી શકે છે, તેમની લાઇબ્રેરીની સમીક્ષા કરી શકે છે અને સર્જક સ્ટુડિયોમાંથી સામગ્રીને ટ્રૅક કરી શકે છે.',
  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'નિર્માતાઓએ ચોક્કસ શીર્ષકો, વર્ણનો, શ્રેણીઓ, ભાષાઓ, થંબનેલ્સ, કૅપ્શન્સ, દૃશ્યતા અને શેડ્યૂલિંગ સેટિંગ્સ પ્રદાન કરવી આવશ્યક છે. સુનિશ્ચિત વિડિઓઝ તેમના નિર્ધારિત સમય અને સફળ પ્રક્રિયા સુધી સાર્વજનિક નથી.',
  'curl --request GET \\\\ --url' => 'curl --request GET \\\\ --url',
  'Current upload categories' => 'વર્તમાન અપલોડ શ્રેણીઓ',
  'Data is used to authenticate users, publish and process content, show videos and channels, personalize account preferences, prevent abuse, support moderation, provide admin analytics, and keep creator and viewer features working.' => 'ડેટાનો ઉપયોગ વપરાશકર્તાઓને પ્રમાણિત કરવા, સામગ્રી પ્રકાશિત કરવા અને પ્રક્રિયા કરવા, વિડિઓઝ અને ચેનલ્સ બતાવવા, એકાઉન્ટ પસંદગીઓને વ્યક્તિગત કરવા, દુરુપયોગ અટકાવવા, મધ્યસ્થતાને સમર્થન આપવા, એડમિન વિશ્લેષણ પ્રદાન કરવા અને સર્જક અને દર્શક સુવિધાઓને કાર્યરત રાખવા માટે વપરાય છે.',
