  'Find answers, get support, and learn how to use PlayHub’s upload, account, creator, and admin features.' => 'જવાબો શોધો, સમર્થન મેળવો અને PlayHub ના વાસ્તવિક અપલોડ, એકાઉન્ટ, સર્જક અને એડમિન સુવિધાઓનો ઉપયોગ કેવી રીતે કરવો તે જાણો.',
  'Find practical support for account access, uploads, playback, creator tools, and moderation.' => 'એકાઉન્ટ ઍક્સેસ, અપલોડ્સ, પ્લેબેક, સર્જક સાધનો અને મધ્યસ્થતા માટે વ્યવહારુ સમર્થન મેળવો.',
