  'Global and remote' => 'વૈશ્વિક અને દૂરસ્થ',
  'Go to Upload, choose your video file, add required details, select category and language, add a thumbnail, then publish. Large files upload in chunks.' => 'અપલોડ પર જાઓ, તમારી વિડિઓ ફાઇલ પસંદ કરો, જરૂરી વિગતો ઉમેરો, શ્રેણી અને ભાષા પસંદ કરો, થંબનેલ ઉમેરો, પછી પ્રકાશિત કરો. મોટી ફાઇલો હિસ્સામાં અપલોડ થાય છે.',
  'Guest mode' => 'અતિથિ મોડ',
  'Have a question, feedback, partnership idea, or support request? Send it through the backend form and admins will see it in the Support dashboard.' => 'કોઈ પ્રશ્ન, પ્રતિસાદ, ભાગીદારીનો વિચાર અથવા સમર્થન વિનંતી છે? તેને બેકએન્ડ ફોર્મ દ્વારા મોકલો અને એડમિન તેને સપોર્ટ ડેશબોર્ડમાં જોશે.',
  'High priority' => 'ઉચ્ચ અગ્રતા',
