  'How do I report inappropriate content?' => 'હું અયોગ્ય સામગ્રીની જાણ કેવી રીતે કરી શકું?',
  'How do I update password or two-factor authentication?' => 'હું પાસવર્ડ અથવા દ્વિ-પરિબળ પ્રમાણીકરણ કેવી રીતે અપડેટ કરી શકું?',
  'How do I upload a video?' => 'હું વિડિઓ કેવી રીતે અપલોડ કરી શકું?',
  'How do uploads work?' => 'અપલોડ્સ કેવી રીતે કામ કરે છે?',
  'How is my privacy protected?' => 'મારી ગોપનીયતા કેવી રીતે સુરક્ષિત છે?',
  'How many upload languages are available?' => 'કેટલી અપલોડ ભાષાઓ ઉપલબ્ધ છે?',
  'How PlayHub uses cookies and browser storage for sessions, security, preferences, and playback.' => 'કેવી રીતે PlayHub સત્રો, સુરક્ષા, પસંદગીઓ અને પ્લેબેક માટે કૂકીઝ અને બ્રાઉઝર સ્ટોરેજનો ઉપયોગ કરે છે.',
  'How this PlayHub deployment handles account, content, activity, security, and preference data.' => 'આ PlayHub ડિપ્લોયમેન્ટ એકાઉન્ટ, સામગ્રી, પ્રવૃત્તિ, સુરક્ષા અને પસંદગીના ડેટાને કેવી રીતે હેન્ડલ કરે છે.',
  'How to upload your first video' => 'તમારી પ્રથમ વિડિઓ કેવી રીતે અપલોડ કરવી',
  'I need help with my account' => 'મને મારા એકાઉન્ટમાં મદદની જરૂર છે',
  'icon-button mini-icon' => 'આઇકન-બટન મીની-આઇકન',
  'If approved, payment is returned through the original method.' => 'જો મંજૂર થાય, તો ચુકવણી મૂળ પદ્ધતિ દ્વારા પરત કરવામાં આવે છે.',
  'If no paid transaction exists in the connected billing provider or platform records, there is no platform charge to refund. Refunds can only be reviewed against payment records, subscription IDs, invoices, or transaction references.' => 'જો કનેક્ટેડ બિલિંગ પ્રદાતા અથવા પ્લેટફોર્મ રેકોર્ડ્સમાં કોઈ પેઇડ ટ્રાન્ઝેક્શન અસ્તિત્વમાં નથી, તો રિફંડ માટે કોઈ પ્લેટફોર્મ શુલ્ક નથી. રિફંડની માત્ર વાસ્તવિક ચુકવણી રેકોર્ડ, સબ્સ્ક્રિપ્શન ID, ઇન્વૉઇસ અથવા વ્યવહાર સંદર્ભો સામે જ સમીક્ષા કરી શકાય છે.',
  'Integration rules' => 'એકીકરણ નિયમો',
