  'Not provided' => 'પ્રદાન કરેલ નથી',
  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'આ જમાવટ માટે પ્લેહબ સાઇટ એડમિનિસ્ટ્રેટર દ્વારા અધિકૃત સંપર્ક સરનામાં, બિલિંગ સંપર્કો અને બાહ્ય સપોર્ટ ચેનલો ગોઠવવા જોઈએ. આ પૃષ્ઠ ઇરાદાપૂર્વક વણચકાસાયેલ ઇમેઇલ સરનામાં પ્રદર્શિત કરતું નથી.',
  'On this page' => 'આ પૃષ્ઠ પર',
  'Open Help Center' => 'હેલ્પ સેન્ટર ખોલો',
  'Open settings' => 'સેટિંગ્સ ખોલો',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'સેટિંગ્સ ખોલો, સુરક્ષા પર જાઓ, પછી પાસવર્ડ અથવા દ્વિ-પરિબળ સંવાદનો ઉપયોગ કરો. રૂપરેખાંકિત કરવામાં આવે ત્યારે ટુ-ફેક્ટર ડિલિવરી ઇમેઇલ અથવા ફોનને સપોર્ટ કરે છે.',
  'Operational snapshot' => 'ઓપરેશનલ સ્નેપશોટ',
  'Optional, but recommended' => 'વૈકલ્પિક, પરંતુ ભલામણ કરેલ',
  'Other' => 'અન્ય',
  'Partnerships, press, and platform operations.' => 'ભાગીદારી, પ્રેસ અને પ્લેટફોર્મ કામગીરી.',
  'Payment help' => 'ચુકવણી મદદ',
  'Platform' => 'પ્લેટફોર્મ',
  'Playback' => 'પ્લેબેક',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'જ્યારે અધિકૃત પ્લેટફોર્મ સુવિધાઓ સાથે લિંક કરવામાં આવે છે ત્યારે પ્લેબેક પ્રગતિ, પછીથી જોવાની સ્થિતિ, પસંદ, ટિપ્પણીઓ, સબ્સ્ક્રિપ્શન્સ, સૂચનાઓ અને એડમિન એનાલિટિક્સ ડેટાબેઝમાં સંગ્રહિત થાય છે.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'પ્લેબેક, ટિપ્પણીઓ, પસંદ, પછીથી જુઓ, સબ્સ્ક્રિપ્શન્સ, સૂચનાઓ, સંદેશાઓ, પ્લેલિસ્ટ્સ અને ભાષા સેટિંગ્સ મુખ્ય નેવિગેશન અને એકાઉન્ટ મેનૂ દ્વારા ઉપલબ્ધ છે.',
  'PlayHub' => 'પ્લેહબ',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub એ એક એકાઉન્ટમાંથી સર્જક સામગ્રીને અપલોડ કરવા, જોવા, શેડ્યૂલ કરવા, મેનેજ કરવા અને મધ્યસ્થી કરવા માટેનું વિડિયો પ્લેટફોર્મ છે.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub એ આ જમાવટ પર ચાલતું વિડિયો પ્લેટફોર્મ છે, જે સર્જકો, દર્શકો, સમુદાયો અને પ્લેટફોર્મ ઓપરેટરો માટે બનાવવામાં આવ્યું છે.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'પ્લેહબ એક પ્લેટફોર્મ પરથી સર્જક ચેનલો, વિડિયો અપલોડ્સ, શેડ્યૂલ કરેલ પ્રકાશન, સબ્સ્ક્રિપ્શન્સ, ટિપ્પણીઓ, પ્લેલિસ્ટ્સ, પછીથી જુઓ, લાઇવ સામગ્રી પૃષ્ઠો અને વહીવટી સાધનો પ્રદાન કરે છે.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub લોગિન સત્રો, API પ્રમાણીકરણ, CSRF/સુરક્ષા વર્તન, ભાષા પસંદગી, થીમ પસંદગી, એકાઉન્ટ મેનૂ સ્થિતિ અને એપ્લિકેશનને કાર્ય કરવા માટે જરૂરી અન્ય સુવિધાઓ માટે આવશ્યક કૂકીઝ અને બ્રાઉઝર સ્ટોરેજનો ઉપયોગ કરે છે.',
  'playhub_language, theme' => 'playhub_language, થીમ',
  'Popular questions' => 'લોકપ્રિય પ્રશ્નો',
  'Preference storage' => 'પસંદગી સંગ્રહ',
  'Privacy Policy' => 'ગોપનીયતા નીતિ',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'ગોપનીયતા, કૂકી, એકાઉન્ટ સુરક્ષા, સમર્થન સંદેશાઓ અને મધ્યસ્થતા ડેટાને PlayHub સાથે જોડાયેલ નીતિઓ અને બેકએન્ડ રેકોર્ડ્સ દ્વારા નિયંત્રિત કરવામાં આવે છે.',
  'Profile, login, security, and settings help.' => 'પ્રોફાઇલ, લોગિન, સુરક્ષા અને સેટિંગ્સ મદદ કરે છે.',
  'Profile, security, and preferences.' => 'પ્રોફાઇલ, સુરક્ષા અને પસંદગીઓ.',
  'Public API route' => 'સાર્વજનિક API રૂટ',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'સાર્વજનિક JSON એન્ડપોઇન્ટ્સમાં ડિપ્લોયમેન્ટ સ્ટેટસ માટે /api/health અને અપલોડ કેટેગરીઝ, ભાષાઓ, મર્યાદાઓ, ચંક સાઇઝ અને ટ્રેન્ડિંગ ટૅગ્સ માટે /api/upload-optionsનો સમાવેશ થાય છે.',
