  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'રિફંડ હેન્ડલિંગ વાસ્તવિક બિલિંગ રેકોર્ડ્સ અને એડમિનિસ્ટ્રેટર સમીક્ષા સાથે જોડાયેલું છે. જો બિલિંગ આ જમાવટ માટે ગોઠવેલ નથી, તો રિફંડ માટે કોઈ પ્લેટફોર્મ શુલ્ક નથી.',
