  'Scheduled video release and reminders.' => 'સુનિશ્ચિત વિડિઓ પ્રકાશન અને રીમાઇન્ડર્સ.',
  'Scheduled videos' => 'સુનિશ્ચિત વિડિઓઝ',
  'Scheduling a video release' => 'વિડિઓ રિલીઝ શેડ્યૂલ કરી રહ્યું છે',
  'Search for answers...' => 'જવાબો શોધો...',
  'Search help articles, topics, or questions...' => 'સહાય લેખો, વિષયો અથવા પ્રશ્નો શોધો...',
  'Select a reason' => 'કારણ પસંદ કરો',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'એક અથવા વધુ વિડિઓ ફાઇલો પસંદ કરો, જરૂરી વિગતો દાખલ કરો, શ્રેણી અને ભાષા પસંદ કરો, થંબનેલ ઉમેરો, દૃશ્યતા પસંદ કરો અને પ્રકાશિત કરો. સર્વર પ્રક્રિયા કરવાનું શરૂ કરે તે પહેલાં મોટી ફાઇલોને હિસ્સામાં અપલોડ કરવામાં આવે છે.',
  'Send a message and it will be saved for admins.' => 'એક સંદેશ મોકલો અને તે સંચાલકો માટે સાચવવામાં આવશે.',
  'Send billing details to admin support for review.' => 'સમીક્ષા માટે એડમિન સપોર્ટને બિલિંગ વિગતો મોકલો.',
  'Send message' => 'સંદેશ મોકલો',
  'Send order details through the refund popup.' => 'રિફંડ પોપઅપ દ્વારા ઓર્ડર વિગતો મોકલો.',
