  'Service operation' => 'સેવા કામગીરી',
  'session, token' => 'સત્ર, ટોકન',
  'Settings and login' => 'સેટિંગ્સ અને લોગિન',
  'Short summary' => 'સંક્ષિપ્ત સારાંશ',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'સાઇન ઇન કરો અને એકાઉન્ટ, પ્રોફાઇલ, પાસવર્ડ, સૂચના, ગોપનીયતા અને સર્જકની પસંદગીઓ માટે સેટિંગ્સનો ઉપયોગ કરો. સર્જક અપલોડ અને સામગ્રી સમસ્યાઓમાં વિડિઓ શીર્ષક, ચેનલ, બ્રાઉઝર અને અપલોડ પૃષ્ઠ પર દર્શાવેલ કોઈપણ પ્રક્રિયા ભૂલ શામેલ હોવી જોઈએ.',
  'Sign in for account support' => 'એકાઉન્ટ સપોર્ટ માટે સાઇન ઇન કરો',
  'Signed in' => 'સાઇન ઇન કર્યું',
  'Start uploading' => 'અપલોડ કરવાનું શરૂ કરો',
  'Still can’t find an answer?' => 'હજુ પણ જવાબ શોધી શકતા નથી?',
  'Stored for admins' => 'સંચાલકો માટે સંગ્રહિત',
  'Stores language, theme, and interface preferences.' => 'ભાષા, થીમ અને ઇન્ટરફેસ પસંદગીઓ સ્ટોર કરે છે.',
  'Studio, playlists, analytics, channels.' => 'સ્ટુડિયો, પ્લેલિસ્ટ્સ, એનાલિટિક્સ, ચૅનલ્સ.',
  'Submit a billing or refund message to admin support.' => 'એડમિન સપોર્ટ પર બિલિંગ અથવા રિફંડ સંદેશ સબમિટ કરો.',
  'Submit refund request' => 'રિફંડની વિનંતી સબમિટ કરો',
  'Submit request' => 'વિનંતી સબમિટ કરો',
  'Subscription cancellation' => 'સબ્સ્ક્રિપ્શન રદ',
  'Support dashboard' => 'સપોર્ટ ડેશબોર્ડ',
  'System status' => 'સિસ્ટમ સ્થિતિ',
  'Table' => 'ટેબલ',
  'Taxonomies' => 'વર્ગીકરણ',
  'Technical issue' => 'ટેકનિકલ સમસ્યા',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'વર્તમાન PlayHub API અને અપલોડ વર્કફ્લો સાથે એકીકરણ માટે તકનીકી નોંધો.',
  'Tell us more about your question or request...' => 'તમારા પ્રશ્ન અથવા વિનંતી વિશે અમને વધુ કહો...',
  'Terms of Use' => 'ઉપયોગની શરતો',
  'The configured' => 'રૂપરેખાંકિત',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ડેવલપર પેજ લાઈવ લારાવેલ બેકએન્ડ સાથે જોડાયેલ છે: રૂટ ઈન્વેન્ટરી, ડેટાબેઝ કાઉન્ટ, અપલોડ મર્યાદા અને પ્લેટફોર્મ મેટાડેટા /api/developers પરથી લોડ કરવામાં આવે છે.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'ફ્રન્ટએન્ડ પસંદ કરેલી ભાષા, થીમ, પ્લેબેક કતાર, ઘડિયાળની પ્રગતિ અને ઈન્ટરફેસ સ્થિતિ જેવી પસંદગીઓને સંગ્રહિત કરે છે જેથી અનુભવ સમગ્ર પૃષ્ઠ નેવિગેશન અને ફરીથી લોડ પર સુસંગત રહે.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'પ્રોસેસિંગ જોબ પ્રસ્તુતિઓને એન્કોડ કરે છે, જ્યારે જરૂર પડે ત્યારે થંબનેલ્સ બનાવે છે, કૅપ્શન્સ સ્ટોર કરે છે અને પ્રક્રિયા પૂર્ણ થાય ત્યારે વિડિયોઝને તૈયાર ચિહ્નિત કરે છે. ભાવિ શેડ્યૂલ કરેલા વીડિયો જ્યાં સુધી શેડ્યૂલર તેમને રિલીઝ ન કરે ત્યાં સુધી ખાનગી રહે છે.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'અપલોડ સિસ્ટમ ડેટાબેઝ-બેક્ડ છે, API માંથી શ્રેણીઓ અને ભાષાઓને સપોર્ટ કરે છે, અપલોડ કરેલા વિડિઓઝ પર પ્રક્રિયા કરે છે, થંબનેલ્સ અને કૅપ્શન્સ સ્ટોર કરે છે અને શેડ્યૂલ કરેલી સામગ્રી તેના પ્રકાશન સમય સુધી ખાનગી રાખે છે.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'આ પૃષ્ઠ સમજાવે છે કે કેવી રીતે PlayHub સત્રો, સુરક્ષા, પસંદગીઓ, પ્લેબેક અને પ્રમાણિત સુવિધાઓ માટે કૂકીઝ અને બ્રાઉઝર સ્ટોરેજનો ઉપયોગ કરે છે.',
  'Ticket source' => 'ટિકિટ સ્ત્રોત',
  'Top content categories' => 'ટોચની સામગ્રી શ્રેણીઓ',
  'Topic' => 'વિષય',
  'Transaction / invoice' => 'ટ્રાન્ઝેક્શન / ઇન્વોઇસ',
  'Transaction / invoice ID' => 'ટ્રાન્ઝેક્શન / ઇન્વોઇસ ID',
  'Unable to send message.' => 'સંદેશ મોકલવામાં અસમર્થ.',
  'Unable to submit refund request.' => 'રિફંડની વિનંતી સબમિટ કરવામાં અસમર્થ.',
  'Understanding admin support tickets' => 'એડમિન સપોર્ટ ટિકિટને સમજવું',
  'Upload and processing help' => 'અપલોડ અને પ્રક્રિયા સહાય',
  'Upload chunks' => 'હિસ્સા અપલોડ કરો',
  'Upload issues' => 'અપલોડ સમસ્યાઓ',
  'Upload languages' => 'ભાષાઓ અપલોડ કરો',
  'Upload limit' => 'અપલોડ મર્યાદા',
  'Upload options' => 'અપલોડ વિકલ્પો',
  'Upload or processing' => 'અપલોડ અથવા પ્રક્રિયા',
  'Upload page' => 'અપલોડ પૃષ્ઠ',
  'Upload pipeline' => 'પાઇપલાઇન અપલોડ કરો',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'લાઇવ PlayHub ડેટા સાથે અપલોડ કરો, જુઓ, સબ્સ્ક્રાઇબ કરો, મધ્યમ કરો અને બિલ્ડ કરો.',
  'Uploaded videos' => 'અપલોડ કરેલા વીડિયો',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'અપલોડ કરેલા વિડિયોને પ્લે કરી શકાય તેવા પ્રસ્તુતિઓમાં એન્કોડ કરવામાં આવે છે. પ્રક્રિયાનો સમય ફાઇલના કદ, અવધિ, સર્વર લોડ અને કતારની સ્થિતિ પર આધાર રાખે છે. અપલોડ પૃષ્ઠ અને નિર્માતા સ્ટુડિયો વિડિઓ રેકોર્ડમાંથી વાસ્તવિક પ્રક્રિયા સ્થિતિ દર્શાવે છે.',
  'Uploads, scheduling, and processing are available.' => 'અપલોડ, શેડ્યૂલિંગ અને પ્રોસેસિંગ ઉપલબ્ધ છે.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'સર્જક વર્કફ્લો માટે /api/વિડિયોઝ, ચેનલ એન્ડપોઇન્ટ્સ અને પ્રમાણિત રૂટ્સનો ઉપયોગ કરો.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'વિડિઓઝ અને ટિપ્પણીઓ માટે બિલ્ટ-ઇન રિપોર્ટ ક્રિયાઓનો ઉપયોગ કરો જેથી વ્યવસ્થાપકો ચોક્કસ સામગ્રી સંદર્ભ પ્રાપ્ત કરે. એડમિન ડેશબોર્ડ પૃષ્ઠો વપરાશકર્તાઓ, સામગ્રી, અહેવાલો, મુદ્રીકરણ, વિશ્લેષણ, સમર્થન, ભૂમિકાઓ અને સિસ્ટમ સેટિંગ્સ માટે લાઇવ ડેટાબેઝ ડેટાનો ઉપયોગ કરે છે.',
  'Use Contact Us' => 'અમારો સંપર્ક કરો નો ઉપયોગ કરો',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'સામાન્ય API વિનંતીઓ અને ફાઇલ અપલોડ્સ માટે ફોર્મડેટા માટે JSON નો ઉપયોગ કરો. માન્યતાને બાયપાસ કરશો નહીં: શ્રેણીઓ અને ભાષાઓ ડેટાબેઝ ID છે, દૃશ્યતા સાર્વજનિક, અસૂચિબદ્ધ અથવા ખાનગી સુધી મર્યાદિત છે અને કૅપ્શન્સ SRT, VTT અથવા TXT ફાઇલોને સ્વીકારે છે.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'તમારી પ્રોફાઇલ, સુરક્ષા, પાસવર્ડ, દ્વિ-પરિબળ ડિલિવરી, ઉપકરણો, પસંદગીઓ અને સૂચના વિકલ્પો અપડેટ કરવા માટે સેટિંગ્સનો ઉપયોગ કરો. જો તમે તમારું એકાઉન્ટ એક્સેસ કરી શકતા નથી, તો લોગિન ફ્લોનો ઉપયોગ કરો અને સાઇટ એડમિનિસ્ટ્રેટરને એકાઉન્ટ ઇમેઇલ પ્રદાન કરો.',
  'Use the contact form' => 'સંપર્ક ફોર્મનો ઉપયોગ કરો',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'વિડિઓઝ, ટિપ્પણીઓ અને સમુદાય પોસ્ટ્સ પર અહેવાલ ક્રિયાઓનો ઉપયોગ કરો જેથી વ્યવસ્થાપકો ચોક્કસ સામગ્રી સંદર્ભ પ્રાપ્ત કરે.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'જ્યારે સામગ્રી પ્લેટફોર્મ નિયમોનું ઉલ્લંઘન કરી શકે છે ત્યારે વિડિઓ, ટિપ્પણીઓ અને સમુદાય પોસ્ટ્સ પર રિપોર્ટ ક્રિયાઓનો ઉપયોગ કરો. આ અહેવાલો વાસ્તવિક સામગ્રી રેકોર્ડ સાથે જોડાયેલા છે અને સામાન્ય સંદેશ કરતાં વધુ સારા છે કારણ કે સંચાલકો ચોક્કસ આઇટમની સમીક્ષા કરી શકે છે.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'એકાઉન્ટ હેલ્પ, કન્ટેન્ટ રિપોર્ટ્સ, ટેક્નિકલ સમસ્યાઓ અને એડમિનિસ્ટ્રેટર વિનંતીઓ માટે યોગ્ય PlayHub ચેનલનો ઉપયોગ કરો.',
  'Video categories' => 'વિડિઓ શ્રેણીઓ',
  'Video for everyone. Built for creators and viewers.' => 'દરેક માટે વિડિઓ. વાસ્તવિક પ્લેટફોર્મ ડેટામાંથી બનાવેલ છે.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'વિડિયો અપલોડ, શેડ્યુલિંગ, થંબનેલ્સ અને પ્રોસેસિંગ સમસ્યાઓ.',
  'Videos, thumbnails, captions, processing.' => 'વિડિઓઝ, થંબનેલ્સ, કૅપ્શન્સ, પ્રક્રિયા.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'દર્શકો શ્રેણીઓ બ્રાઉઝ કરી શકે છે, વિડિઓઝ શોધી શકે છે, સામગ્રી જોઈ શકે છે, ચેનલ્સ પર સબ્સ્ક્રાઇબ કરી શકે છે, પછીથી જોવા માટે વિડિઓઝ સાચવી શકે છે, ટિપ્પણી કરી શકે છે, સૂચનાઓ પ્રાપ્ત કરી શકે છે અને ભાષા અને ઍક્સેસિબિલિટી પસંદગીઓનું સંચાલન કરી શકે છે.',
  'Viewing and community help' => 'જોવા અને સમુદાય મદદ',
  'Waiting for backend endpoint inventory.' => 'બેકએન્ડ એન્ડપોઇન્ટ ઇન્વેન્ટરીની રાહ જોઈ રહ્યાં છીએ.',
  'We’re here to help.' => 'અમે મદદ કરવા માટે અહીં છીએ.',
  'What is PlayHub?' => 'PlayHub શું છે?',
  'What PlayHub does' => 'PlayHub શું કરે છે',
  'Where do contact messages go?' => 'સંપર્ક સંદેશાઓ ક્યાં જાય છે?',
  'Why is my video still processing?' => 'શા માટે મારી વિડિઓ હજુ પણ પ્રક્રિયા કરી રહી છે?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'હા. અપલોડ પૃષ્ઠ પર મૂળ શેડ્યૂલ તારીખ અને સમય ફીલ્ડનો ઉપયોગ કરો. બેકએન્ડ શેડ્યૂલ_એટ સ્ટોર કરે છે, વિડિયો પર પ્રક્રિયા કરે છે, તારીખ ભવિષ્યમાં હોય ત્યારે તેને ખાનગી રાખે છે અને જ્યારે લારાવેલ શેડ્યૂલર નિર્ધારિત સમય પછી ચાલે છે ત્યારે તેને રિલીઝ કરે છે.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'હા. અપલોડ પર મૂળ શેડ્યૂલ ફીલ્ડનો ઉપયોગ કરો. બેકએન્ડ શેડ્યૂલ_એટ સ્ટોર કરે છે અને જ્યારે શેડ્યૂલનો સમય પહોંચી જાય ત્યારે પ્રક્રિયા કર્યા પછી વિડિયો રિલીઝ કરે છે.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'તમે અતિથિ તરીકે બ્રાઉઝ કરી રહ્યાં છો. એકાઉન્ટ-વિશિષ્ટ સાધનોને ઍક્સેસ કરવા માટે સાઇન ઇન કરો.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'તમે તમારા એકાઉન્ટ ઓળખપત્રો, પ્રોફાઇલ પ્રવૃત્તિ, અપલોડ કરેલી સામગ્રી, ટિપ્પણીઓ, સંદેશાઓ અને તમારા એકાઉન્ટમાંથી કરવામાં આવતી કોઈપણ સર્જક અથવા વ્યવસ્થાપક ક્રિયાઓ માટે જવાબદાર છો. મજબૂત પાસવર્ડનો ઉપયોગ કરો અને દ્વિ-પરિબળ વિતરણ પદ્ધતિઓ વર્તમાન રાખો.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'તમે તમારા બ્રાઉઝર સેટિંગ્સમાં બ્રાઉઝર કૂકીઝ અને સ્થાનિક સ્ટોરેજ સાફ કરી શકો છો. આવશ્યક સ્ટોરેજ સાફ કરવાથી તમે સાઇન આઉટ થઈ શકો છો, ભાષા/થીમ પસંદગીઓ રીસેટ કરી શકો છો, સ્થાનિક પ્લેબેક સ્થિતિ દૂર કરી શકો છો અને તમારે ફરીથી લોગ ઇન કરવાની જરૂર પડે છે.',
  'You receive a response by email.' => 'તમને ઈમેલ દ્વારા પ્રતિસાદ મળે છે.',
  'You’re in control' => 'તમે નિયંત્રણમાં છો',
  'Your choices' => 'તમારી પસંદગીઓ',
